content:
:root {
  font-family: Inter, system-ui, Avenir, Helvetica, Arial, sans-serif;
  line-height: 1.5;
  font-weight: 400;

  color-scheme: light;
  color: #213547;
  background-color: #f8fafc;

  font-synthesis: none;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  margin: 0;
  display: flex;
  place-content: center;
  min-width: 320px;
  min-height: 100vh;
}

* {
  box-sizing: border-box;
}

.app-container {
  max-width: 900px;
  width: 100%;
  margin: 0 auto;
  padding: 2rem 1rem;
}

.header {
  margin-bottom: 1.5rem;
  text-align: center;
}

.title {
  font-size: 1.875rem;
  font-weight: 700;
  color: #1e293b;
  margin: 0 0 1rem 0;
}

.controls {
  display: flex;
  justify-content: flex-end;
  margin-bottom: 1rem;
}

.search-input {
  padding: 0.5rem 1rem;
  font-size: 0.95rem;
  border: 1px solid #cbd5e1;
  border-radius: 0.375rem;
  width: 100%;
  max-width: 300px;
  outline: none;
  transition: border-color 0.2s, box-shadow 0.2s;
}

.search-input:focus {
  border-color: #3b82f6;
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.15);
}

.table-container {
  background-color: #ffffff;
  border-radius: 0.5rem;
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
  overflow-x: auto;
}

.employee-table {
  width: 100%;
  border-collapse: collapse;
  text-align: left;
  font-size: 0.95rem;
}

.employee-table th {
  background-color: #f1f5f9;
  color: #475569;
  font-weight: 600;
  padding: 0.75rem 1rem;
  border-bottom: 1px solid #e2e8f0;
  user-select: none;
}

.th-sortable {
  cursor: pointer;
  transition: background-color 0.2s;
}

.th-sortable:hover {
  background-color: #e2e8f0;
  color: #1e293b;
}

.th-sortable.sorted {
  color: #2563eb;
  background-color: #e0f2fe;
}

.td {
  padding: 0.75rem 1rem;
  border-bottom: 1px solid #f1f5f9;
  color: #334155;
}

.employee-table tbody tr:last-child .td {
  border-bottom: none;
}

.employee-table tbody tr:hover {
  background-color: #f8fafc;
}

.no-result {
  text-align: center;
  padding: 2rem;
  color: #64748b;
  font-style: italic;
}

@media (max-width: 640px) {
  .app-container {
    padding: 1rem 0.5rem;
  }

  .controls {
    justify-content: stretch;
  }

  .search-input {
    max-width: 100%;
  }
}

export interface Employee {
  id: number;
  name: string;
  department: string;
  age: number;
}

export type SortField = 'id' | 'name' | 'department' | 'age';

export type SortOrder = 'asc' | 'desc';

import { useState, useMemo } from 'react';
import './index.css';
import { Employee, SortField, SortOrder } from './types';

const initialEmployees: Employee[] = [
  { id: 1, name: '山田 太郎', department: '開発部', age: 28 },
  { id: 2, name: '佐藤 花子', department: '人事部', age: 32 },
  { id: 3, name: '鈴木 一郎', department: '営業部', age: 45 },
  { id: 4, name: '高橋 恵子', department: '開発部', age: 26 },
  { id: 5, name: '田中 健太', department: '総務部', age: 38 },
  { id: 6, name: '伊藤 葵', department: '営業部', age: 29 },
  { id: 7, name: '渡辺 翔', department: '開発部', age: 31 },
  { id: 8, name: '山本 美咲', department: '人事部', age: 24 },
  { id: 9, name: '中村 蓮', department: '総務部', age: 41 },
  { id: 10, name: '小林 結衣', department: '営業部', age: 27 },
];

export default function App() {
  const [searchQuery, setSearchQuery] = useState('');
  const [sortField, setSortField] = useState<SortField>('id');
  const [sortOrder, setSortOrder] = useState<SortOrder>('asc');

  const handleSort = (field: SortField) => {
    if (sortField === field) {
      setSortOrder(sortOrder === 'asc' ? 'desc' : 'asc');
    } else {
      setSortField(field);
      setSortOrder('asc');
    }
  };

  const filteredAndSortedEmployees = useMemo(() => {
    let result = initialEmployees.filter((emp) =>
      emp.name.toLowerCase().includes(searchQuery.toLowerCase())
    );

    result.sort((a, b) => {
      let aVal = a[sortField];
      let bVal = b[sortField];

      if (typeof aVal === 'string' && typeof bVal === 'string') {
        const comp = aVal.localeCompare(bVal, 'ja');
        return sortOrder === 'asc' ? comp : -comp;
      } else {
        if (aVal < bVal) return sortOrder === 'asc' ? -1 : 1;
        if (aVal > bVal) return sortOrder === 'asc' ? 1 : -1;
        return 0;
      }
    });

    return result;
  }, [searchQuery, sortField, sortOrder]);

  return (
    <div className="app-container">
      <header className="header">
        <h1 className="title">社員一覧アプリ</h1>
        <div className="controls">
          <input
            type="text"
            className="search-input"
            placeholder="名前で絞り込み..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
          />
        </div>
      </header>
      <div className="table-container">
        <table className="employee-table">
          <thead>
            <tr>
              <th
                className={`th-sortable ${sortField === 'id' ? 'sorted' : ''}`}
                onClick={() => handleSort('id')}
              >
                ID {sortField === 'id' && (sortOrder === 'asc' ? '▲' : '▼')}
              </th>
              <th
                className={`th-sortable ${sortField === 'name' ? 'sorted' : ''}`}
                onClick={() => handleSort('name')}
              >
                名前 {sortField === 'name' && (sortOrder === 'asc' ? '▲' : '▼')}
              </th>
              <th
                className={`th-sortable ${sortField === 'department' ? 'sorted' : ''}`}
                onClick={() => handleSort('department')}
              >
                部署 {sortField === 'department' && (sortOrder === 'asc' ? '▲' : '▼')}
              </th>
              <th
                className={`th-sortable ${sortField === 'age' ? 'sorted' : ''}`}
                onClick={() => handleSort('age')}
              >
                年齢 {sortField === 'age' && (sortOrder === 'asc' ? '▲' : '▼')}
              </th>
            </tr>
          </thead>
          <tbody>
            {filteredAndSortedEmployees.length > 0 ? (
              filteredAndSortedEmployees.map((emp) => (
                <tr key={emp.id}>
                  <td className="td">{emp.id}</td>
                  <td className="td">{emp.name}</td>
                  <td className="td">{emp.department}</td>
                  <td className="td">{emp.age}</td>
                </tr>
              ))
            ) : (
              <tr>
                <td colSpan={4} className="no-result">
                  該当する社員が見つかりません。
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}
